title "Precise edits"
key a minor
track bass acid {}
track drums drums {}
phrase hook { . . 5~*2?70 - }
pattern p acid slot=7 { swing = 54% use hook use hook +12 }
pattern shared { use hook }
pattern beat drums { bd: x.Xx3; }
scene main { bass = p drums=beat }
scene other { bass=shared }
song { main*2 other }

